tools.example:
model = createpde(1);
geometryFromEdges(model, @lshapeg);
applyBoundaryCondition(model, "dirichlet", Edge=1:model.Geometry.NumEdges, u=0);
specifyCoefficients(model, m=0, d=0, c=1, a=0, f=1);
generateMesh(model, Hmax=0.1);
results = solvepde(model);
pdeplot(model, XYData=results.NodalSolution)

gm = fegeometry("Bracket.stl");
model = femodel(AnalysisType="structuralStatic", Geometry=gm);
model.MaterialProperties = materialProperties(YoungsModulus=200e9, PoissonsRatio=0.3);
model.FaceBC(3) = faceBC(Constraint="fixed");
model.FaceLoad(2) = faceLoad(SurfaceTraction=[0 0 -1e4]);
model = generateMesh(model);
R = solve(model);
pdeplot3D(R.Mesh, ColorMapData=R.VonMisesStress, Deformation=R.Displacement)

gm = fegeometry("PlateHolePlanar.stl");
pdegplot(gm, FaceLabels="on", EdgeLabels="on")
gm = generateMesh(gm, Hmax=2);
pdemesh(gm)

model = createpde;
gm = importGeometry(model, "BracketWithHole.stl");
pdegplot(model, FaceLabels="on", FaceAlpha=0.5)

R1 = [3 4 -1 1 1 -1 -1 -1 1 1]';
C1 = [1 0 0 0.4 zeros(1,6)]';
gd = [R1 C1]; sf = 'R1-C1'; ns = char('R1','C1')';
dl = decsg(gd, sf, ns);
model = createpde;
geometryFromEdges(model, dl);
pdegplot(model, EdgeLabels="on")

load tetmesh
nodes = X'; elements = tet';
model = createpde;
geometryFromMesh(model, nodes, elements);
pdegplot(model, FaceLabels="on", FaceAlpha=0.5)

rect = [3 4 0 2 2 0 0 0 1 1]';
circ = [1 1 0.5 0.3 zeros(1,6)]';
gd = [rect circ];
dl = decsg(gd, 'R-C', char('R','C')');
model = createpde; geometryFromEdges(model, dl);
pdegplot(model, EdgeLabels="on", FaceLabels="on")

gm = multicuboid([1 2], [1 2], [0.5 0.5]);
model = femodel(AnalysisType="thermalSteady", Geometry=gm);
pdegplot(model, CellLabels="on", FaceAlpha=0.4)

gm = multicylinder([5 10], 20, Void=[true false]);   % hollow tube
model = femodel(AnalysisType="structuralStatic", Geometry=gm);
pdegplot(model, FaceLabels="on", FaceAlpha=0.5)

dl = decsg([3 4 0 1 1 0 0 0 1 1]');
gm2 = fegeometry(dl);
gm3 = extrude(gm2, [0.2 0.3]);
pdegplot(gm3, CellLabels="on", FaceAlpha=0.5)

model = createpde;
importGeometry(model, "Block.stl");
mesh = generateMesh(model, Hmax=10, Hface={[1 3], 2}, GeometricOrder="linear");
pdemesh(model)
Q = meshQuality(mesh); fprintf("min quality %.2f\n", min(Q))

model = createpde;
geometryFromEdges(model, @circleg);
generateMesh(model, Hmax=0.2);
pdemesh(model, NodeLabels="off")

Nf = findNodes(model.Mesh, "region", Face=2);
uFace = results.NodalSolution(Nf);
Nn = findNodes(model.Mesh, "nearest", [0.5; 0.5]);

Ec = findElements(model.Mesh, "region", Cell=1);
V = volume(model.Mesh, Ec);
pdemesh(model.Mesh.Nodes, model.Mesh.Elements(:, Ec))

mesh = generateMesh(model, Hmax=0.1);
Q = meshQuality(mesh);
bad = find(Q < 0.3);
pdemesh(mesh.Nodes, mesh.Elements(:, bad))

setInitialConditions(model, 0);
setInitialConditions(model, @(location) exp(-((location.x-0.5).^2 + (location.y-0.5).^2)/0.01), Face=1);
results = solvepde(model, 0:0.01:1);

model.SolverOptions.ReportStatistics = "on";
results = solvepde(model, linspace(0, 2, 41));
u = results.NodalSolution;   % nodes-by-times
pdeplot(model, XYData=u(:, end), Contour="on")

model = createpde; geometryFromEdges(model, @lshapeg);
applyBoundaryCondition(model, "dirichlet", Edge=1:model.Geometry.NumEdges, u=0);
specifyCoefficients(model, m=0, d=1, c=1, a=0, f=0);
generateMesh(model, Hmax=0.05);
R = solvepdeeig(model, [-Inf 100]);
pdeplot(model, XYData=R.Eigenvectors(:,1))

FEM = assembleFEMatrices(model, "nullspace");
u = FEM.B*(FEM.Kc \ FEM.Fc) + FEM.ud;
pdeplot(model, XYData=u)

x = linspace(-1, 1, 101); y = zeros(size(x));
u = interpolateSolution(results, x, y);
plot(x, u); xlabel('x'); ylabel('u(x,0)')

R = solve(model);
pdeplot3D(R.Mesh, ColorMapData=R.Temperature, FaceAlpha=0.6)
colormap("hot"); colorbar

R = solve(model);
viz = pdeviz(R.Mesh, R.Temperature);
viz.MeshVisible = true;
viz.ColorLimits = [290 350];

model.FaceBC(1) = faceBC(Constraint="fixed");
model.FaceBC([4 5]) = faceBC(ZDisplacement=0);
model.FaceBC(6) = faceBC(Temperature=350);

model.CellLoad = cellLoad(Gravity=[0 0 -9.81]);
thermal = solve(thermalModel);
model.CellLoad = cellLoad(Temperature=thermal, ReferenceTemperature=293);

model = createpde("structural", "static-solid");
importGeometry(model, "Bracket.stl");
structuralProperties(model, YoungsModulus=200e9, PoissonsRatio=0.3);
structuralBC(model, Face=4, Constraint="fixed");
structuralBoundaryLoad(model, Face=8, SurfaceTraction=[0 0 -1e4]);
generateMesh(model);
R = solve(model);

model = createpde("thermal", "transient");
geometryFromEdges(model, @squareg);
thermalProperties(model, ThermalConductivity=80, MassDensity=7800, SpecificHeat=450);
thermalBC(model, Edge=1, Temperature=100);
thermalIC(model, 20);
generateMesh(model);
R = solve(model, 0:10:600);

R = solve(model, 0:0.001:0.05);
s = evaluateStress(R);
pdeplot3D(R.Mesh, ColorMapData=s.xx(:, end))

R = solve(thermalModel);
[qx, qy] = evaluateHeatFlux(R);
pdeplot(thermalModel, XYData=R.Temperature, FlowData=[qx qy])

z = linspace(0, 0.1, 50);
T = interpolateTemperature(R, zeros(size(z)), zeros(size(z)), z, numel(R.SolutionTimes));
plot(z, T)
